'use strict';

// impl is never imported directly by the traced app, but exports.wrap
// closes over it. Stubbing impl's body would break wrap().
function impl() {
  const parts = [];
  const seeds = [3, 5, 7, 11, 13, 17, 19, 23];
  for (let i = 0; i < seeds.length; i++) {
    const seed = seeds[i];
    const squared = seed * seed;
    const tagged = `seed:${seed}:sq:${squared}`;
    parts.push(tagged);
  }
  const joined = parts.join('|');
  const checksum = joined
    .split('')
    .reduce((acc, ch) => (acc + ch.charCodeAt(0)) % 9973, 0);
  return { joined, checksum, count: parts.length };
}

exports.impl = impl;
exports.wrap = () => impl();
